// A real, unedited slice of iNaturalist moth observations — but not just any
// 15-minute slice: the last 24 hours (2026-09-15/16) were scanned in
// 15-minute windows (scoped exactly like the live feed itself: taxon_id=47157
// Lepidoptera, without_taxon_id=47224 to exclude butterflies, photos
// required, an appropriately-licensed photo — no place_id, so global, not one
// country) to find the single busiest 15-minute window in that whole day, then
// that exact window's observations were fetched in full and baked in here. A
// basic version of this project used a single ad hoc 15-minute capture
// instead; scanning a full day for the busiest window first means this
// fallback holds meaningfully more real moths to show during an outage.
//
// Filtered to family level or finer (rank_level <= 30 in iNaturalist's own
// scheme — see observation-adapter.js's RANK_LEVELS/isAtLeastFamilyLevel,
// which every observation, live or fallback, is validated against): the
// window's original 497 observations included 3 identified only to order
// (just "Lepidoptera") and 16 to superfamily, neither of which tells a
// viewer anything recognizable about the actual moth — dropped, leaving 478.
// Because this was still optimized for volume rather than identification
// purity, under half of what remains (238/478) is identified all the way to
// species — the rest (mostly genus-level, likely one batch of trap photos
// uploaded and AI-suggested but not yet community-confirmed) render with
// MothStore's shared grey "unknown" profile, same as any live observation
// identified that coarsely would. This is a real, representative mix for
// what a live feed's freshest observations actually look like, not a defect.
//
// This is the last line of defense for a visitor whose very first load can't
// get live data at all (see app.js's fallback-mode wiring). The site has no
// server-side cache of its own (see README's website-only-design phase) — a
// sustained iNaturalist outage now has nothing else standing between it and
// this set, so it deliberately holds enough real, time-spread observations
// (fed through the same ObservationQueue/MothStore pipeline live moths use, at
// real-time pacing — see app.js's createQueue()) to keep the animation
// populated for a good while rather than draining in seconds.
